<?php
$categories=all('SELECT id,name FROM categories ORDER BY name');
$selectedProfile=vs_profile_id($draft);
$preset=$draft['session_preset']??(isset($draft['minutes'])||isset($draft['assignment_limit'])?'custom':'standard');
if (!isset(VS_PRESETS[$preset]) && $preset!=='custom') $preset='custom';
$scopeKind=$draft['scope_kind']??'all';$categoryId=$draft['category_id']??'';
$choice=$draft['cause_choice']??($scopeKind==='all'?'all':($scopeKind==='category'?'category:'.$categoryId:'custom'));
if(str_starts_with($choice,'category:')){$categoryId=substr($choice,9);$scopeKind='category';}
$causeLabel='Wherever needed';foreach($categories as $category)if((string)$category['id']===(string)$categoryId&&$scopeKind==='category')$causeLabel=$category['name'];
if($choice==='custom'&&$scopeKind==='research')$causeLabel='One research question';
$pills=array_slice($categories,0,4);if($scopeKind==='category'&&!in_array((string)$categoryId,array_map(fn($c)=>(string)$c['id'],$pills),true))foreach($categories as $category)if((string)$category['id']===(string)$categoryId)$pills[]=$category;
$minutes=$preset==='custom'?($draft['minutes']??60):VS_PRESETS[$preset]['minutes'];$count=$preset==='custom'?($draft['assignment_limit']??3):VS_PRESETS[$preset]['tasks'];
$icons=['quick'=>'<path d="m13 2-8 12h6l-1 8 9-13h-7z"/>','standard'=>'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>','long'=>'<path d="m2 20 6-12 4 7 3-5 7 10z"/><path d="m5 14 3 2 2-1"/>','unlimited'=>'<path d="M12 12c-3-7-10-5-10 0s7 7 10 0 10-5 10 0-7 7-10 0z"/>'];
?>
<div class="volunteer-start volunteer-design"><h1>Start volunteering</h1><p class="volunteer-subtitle">Bring your own AI. Choose time and scope.</p>
<?php if($error): ?><p class="warning" role="alert"><?=e($error)?></p><?php endif ?>
<form method="post" data-volunteer-setup><?=csrf()?><input type="hidden" name="operation" value="configure">
<fieldset class="volunteer-profile-choice"><legend>What can your AI use?</legend><div class="profile-options"><?php foreach(['restricted_web_v1'=>'Web only','general'=>'Web + tools'] as $profileId=>$label): ?><label><input type="radio" name="session_profile" value="<?=e($profileId)?>" <?=$selectedProfile===$profileId?'checked':''?>><span><?=e($label)?></span></label><?php endforeach ?></div><p class="fine">Web only skips code execution and software tasks.</p></fieldset>
<fieldset class="worker-settings"><label for="volunteer-worker">Research worker</label><select id="volunteer-worker" name="worker_choice" required><option value="">Choose a worker</option><?php foreach(['sol_max'=>'GPT-6.1 Sol · Max · Codex','astra_max'=>'GPT-6 Astra · Max · Codex','custom'=>'Other model / settings (Advanced Options)'] as $value=>$label): ?><option value="<?=e($value)?>" <?=($draft['worker_choice']??(!empty($draft['model'])?'custom':''))===$value?'selected':''?>><?=e($label)?></option><?php endforeach ?></select><p class="fine">Requested (unverified) · <span data-concurrent-summary><?=e($draft['concurrent_limit']??1)?></span> task(s) at a time.</p></fieldset>
<fieldset class="time-settings"><legend>How much time do you have?</legend><p class="time-explanation">Ends at your first limit; No limit runs until Stop.</p>
<div class="time-cards"><?php foreach(VS_PRESETS as $key=>$option): ?><label class="time-card time-<?=e($key)?>"><input type="radio" name="session_preset" value="<?=e($key)?>" <?=$preset===$key?'checked':''?>><span class="time-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><?=$icons[$key]?></svg></span><span class="time-name"><?=e($option['label'])?></span><strong class="time-value"><?=e(match($key){'quick'=>'15 min','standard'=>'60 min','long'=>'3 hrs',default=>'∞'})?></strong><span class="time-task"><?=e($key==='unlimited'?'Until Stop':'or '.$option['tasks'].' '.($option['tasks']===1?'task':'tasks'))?></span></label><?php endforeach ?></div></fieldset>
<fieldset class="cause-settings"><legend>Where should it help?</legend><div class="cause-pills"><label class="cause-pill"><input type="radio" name="cause_choice" value="all" <?=$choice==='all'?'checked':''?> data-cause-label="Wherever needed"><span class="cause-dot" aria-hidden="true"></span><span>Wherever needed</span></label><?php foreach($pills as $index=>$category): ?><label class="cause-pill cause-<?=e($index%4)?>"><input type="radio" name="cause_choice" value="category:<?=e($category['id'])?>" <?=$choice==='category:'.$category['id']?'checked':''?> data-cause-label="<?=e($category['name'])?>"><span class="cause-dot" aria-hidden="true"></span><span><?=e($category['name'])?></span></label><?php endforeach ?></div></fieldset>
<div class="volunteer-finish"><div class="session-summary"><span>Your session</span><strong data-volunteer-summary role="status" aria-live="polite"><?=e($preset==='unlimited'?'Until Stop':$minutes.' min or '.$count.' '.((int)$count===1?'task':'tasks'))?> · <?=e($causeLabel)?></strong></div>
<details class="volunteer-advanced" data-volunteer-advanced <?=$error?'open':''?>><summary>Advanced Options</summary><div class="volunteer-advanced-fields"><?php include __DIR__.'/volunteer-options.php'; ?></div></details>
<button class="connect-ai" type="submit">Connect my AI <span aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></span></button></div>
</form></div>
